#!/usr/bin/env python3
"""Build human-readable reports from completed scored artifacts only."""
from pathlib import Path
import json,datetime
R=Path(__file__).resolve().parents[1]
S=json.loads((R/'results/summary.json').read_text());M=json.loads((R/'results/predictions.metadata.json').read_text());O=json.loads((R/'results/run_outcome.json').read_text());D=json.loads((R/'data/design_summary.json').read_text())
assert M['status']=='completed' and O['exit_code']==0 and S['case_count']==80
E=[json.loads(x) for x in (R/'results/errors.jsonl').read_text().splitlines() if x.strip()]
F=json.loads((R/'freeze_manifest.json').read_text())
def fm(m):return f"{m['correct']}/{m['total']} ({100*m['accuracy']:.2f} %)"
def safe(k):return S['safety'][k]['count']
lines=['# Clef: Pilot für deutschen Bankkundenservice','',f"**Alle drei Felder richtig: {fm(S['metrics']['all_fields_exact'])}.**",'',f"- Anliegen/Route: {fm(S['metrics']['intent'])}",f"- Priorität: {fm(S['metrics']['priority'])}",f"- Nächster Supportschritt: {fm(S['metrics']['next_step'])}",f"- Insgesamt richtige Teilentscheidungen: {fm(S['metrics']['all_field_decisions'])}",'', '## Einordnung','', 'Als einfacher Häufigkeitsmaßstab erreicht die konstante Vorhersage routine beim Prioritätsfeld 64/80 (80 %). Deshalb sind kritische/dringende Fehlzuordnungen und die gemeinsame Drei-Feld-Genauigkeit wichtiger als eine isolierte hohe Prioritätsquote.','', '80 neu geschriebene synthetische Nachrichten für den Privatkundenservice einer fiktiven Bank. Drei native Choice-Felder pro Fall, ein eingefrorener Hauptlauf. Eigener deutscher Support-Pilot; kein BANKING77, keine repräsentative Stichprobe des Bankverkehrs und kein numerischer Vergleich mit Hersteller- oder Jev-Ergebnissen. Andere Testsuiten werden nicht eingerechnet.','', 'Geprüft werden begrenzte Entscheidungen über Route, Dringlichkeit und die Art des nächsten Schritts. Das Modell formuliert keine freie Antwort. Die in den Daten gespeicherten konkreten Rückfragen stammen von den Testautoren, nicht von Clef. Es wird weder Geld bewegt noch eine Karte gesperrt oder ein Rechts-/Erstattungs-/Kreditanspruch entschieden.','', '## Sicherheitsrelevante Fehler','', f"Vollständig richtige kritische Fälle: {fm(S['strata']['priority']['critical']['all_fields_exact'])}. Zwei kritische Nachrichten wurden zur falschen Intent-Route eingeordnet (unerwartete TAN-Anforderung und unautorisierte Lastschrift), obwohl das Modell jeweils critical und security_handoff richtig wählte. Null verfehlte Sicherheitsweiterleitungen bedeutet deshalb nicht, dass alle kritischen Fälle vollständig richtig waren.",'',f"- Kritische Priorität verfehlt: {safe('critical_priority_misses')}/{safe('critical_cases')}",f"- Erforderlichen sofortigen Sicherheitsweg verfehlt: {safe('critical_handoff_misses')}/{safe('critical_cases')}",f"- Kritische Fälle mit mindestens einem dieser beiden Fehler: {safe('critical_safety_case_errors')}/{safe('critical_cases')}",f"- Dringende Fälle fälschlich als routine eingestuft: {safe('urgent_undertriage')}/{safe('urgent_cases')}",f"- Unnötige critical-Einstufungen: {safe('unnecessary_critical_priority')}/{80-safe('critical_cases')} nicht-kritische Referenzfälle",f"- Unnötige Sicherheitsweiterleitungen: {safe('unnecessary_security_handoffs')}/{80-safe('critical_cases')}",f"- Unnötige Eskalationen statt Information/Rückfrage: {safe('unnecessary_escalations')}/{safe('non_escalation_reference_cases')}",'', '„Unnötige Eskalation“ ist hier eng definiert: Referenz guidance oder clarify, Modell specialist_review oder security_handoff. Normale fachliche Prüfaufträge zählen nicht als unnötige Eskalation. Sicherheitskennzahlen sind keine umfassende Messung von Sicherheit; zehn kritische Fälle reichen nicht zum Nachweis seltener Fehlerraten.','', '## Routing-bereite Fälle und notwendige Rückfragen','', 'route_ready bedeutet: Der nächste Supportweg ist aus der Nachricht bestimmbar. Es bedeutet nicht, dass alle Angaben zur späteren Bearbeitung vorliegen; ein Sicherheitsweg kann trotz unklarer Einzelheiten sofort nötig sein. clarification_needed bezeichnet Fälle, in denen zuerst eine konkrete nicht-geheime Sachfrage oder die Reihenfolge geklärt werden muss.','']
for k,v in S['strata']['answerability'].items():lines.append(f"- {k}: alle drei Felder {fm(v['all_fields_exact'])}; nächster Schritt {fm(v['next_step'])}")
lines += ['',f"Verfehlte notwendige Rückfragen: {safe('missed_clarifications')}/14.",'', '## Themen und Sprachformen','', '| Themenstratum | Fälle | Alle drei Felder richtig |','|---|---:|---:|']
for k,v in sorted(S['strata']['topic'].items()):lines.append(f"| {k} | {v['case_count']} | {fm(v['all_fields_exact'])} |")
lines += ['', '| Primärer Sprachform-Tag | Fälle | Alle drei Felder richtig |','|---|---:|---:|']
for k,v in sorted(S['strata']['style'].items()):lines.append(f"| {k} | {v['case_count']} | {fm(v['all_fields_exact'])} |")
lines += ['', 'Die zehn Themenstrata sind absichtlich gleich groß; die Goldlabels sind es nicht. Sprachform-Tags benennen den primären Schwerpunkt, nicht das Fehlen anderer Merkmale. Kategorienhäufigkeiten sind keine Schätzung realer Bankanfragen.','', '## Exakte Goldverteilungen','']
for f,v in sorted(D['gold_label_counts'].items()):lines.append('- '+f+': '+', '.join(f'{k}={n}' for k,n in v.items()))
lines += ['', '## Methode, Freeze und Prüfung','', '- Alle 80 Nachrichten und alle 240 Goldlabels vor dem Modelllauf separat geprüft', '- Separater KI-Prüfer mit sichtbaren Goldlabels; keine verblindete menschliche oder bankfachliche Validierung', '- Der erste Audit fand zwei nicht eindeutig spezifizierte Intents; die Nachrichten/Regeln wurden vor Freeze präzisiert. Goldlabels blieben unverändert', '- Abschließender Audit: 80/80 Fälle und 240/240 Labels konsistent; genaue Prüfprotokolle im audit-Verzeichnis', '- Ein Validatorfehler bei der Reihenfolge von JSON-Schlüsseln wurde vor jeder Inferenz korrigiert; der frühere Freeze und die Begründung sind archiviert. Modellinputs und Gold wurden dadurch nicht verändert', '- Label-freie Requests getrennt von Gold und Metadaten; der Runner kodiert nur das innere request-Objekt, nicht die themenhaltigen IDs', '- Kein Tuning an den Ergebnissen, keine ausgeschlossenen Fehler, keine gekürzten Eingaben', '- Ein bewusst konstruierter Randfall (bank_ambiguous_multi_07) kombiniert globale Dringlichkeit mit zwei gleichrangigen Routen; seine Antwort folgt nur der ausdrücklich fiktiven Regel','', '## Laufzeit und technische Grenzen','', f"- Modell: Cloudflare/clef-flash, Revision {M['revision']}",'- Experimentelle CPU-NF4-Quantisierung des Backbones, originale BF16-Kopf- und Output-Embedding-Gewichte; kein Ersatzmodell',f"- {M['threads']} CPU-Threads, Batch 1, 2048-Token-Grenze",f"- Gemessene Eingabelängen: {S['technical']['input_tokens_min']}–{S['technical']['input_tokens_max']} Tokens; 0 gekürzte Eingaben",f"- Schema-valide Fälle: {S['technical']['schema_valid_cases']}/80",f"- Modell-Forward-Latenz: Median {S['technical']['forward_seconds_median']:.3f} s, p95 {S['technical']['forward_seconds_p95']:.3f} s",f"- Modellladen: {M['load_seconds']:.3f} s, nicht in den Falllatenzen",f"- Maximaler Prozess-RSS laut Runner: {M['max_rss_bytes']/1024**3:.3f} GiB",f"- Repeatability-Probe (erster Fall, außerhalb der Scores): maximale absolute Wahrscheinlichkeitsabweichung {M['repeatability_probe']['repeat_max_absolute_probability_difference']}",'- Der ursprüngliche offizielle Wrapper bleibt Englisch; Kundennachrichten und Anweisungen sind Deutsch', '- Technischer Warmup und erste-Fall-Wiederholung sind aus Genauigkeit und Latenzaggregaten ausgeschlossen', '- Modellrevision, unveränderter Runner, native Anfragen und Paketversionen sind für den wissenschaftlichen Lauf dokumentiert; private Wiederherstellungs- und Hostdiagnostik ist im öffentlichen Paket nicht enthalten', '- CPU-Zeiten gelten ausschließlich für diesen dokumentierten Lauf; keine Hardware- oder Produktionslatenzvergleiche ableiten','', '## Beobachtete Fehlermuster','', '- Drei erforderliche Rückfragen wurden übersprungen: zweimal zugunsten einer Fachprüfung, einmal zugunsten allgemeiner Information', '- Drei routine-Fälle wurden als urgent eingestuft: ausstehender Empfängereingang, doppelte bekannte Lastschrift und noch unbestätigte Doppelüberweisung', '- Eine selbst verursachte technische Login-Sperre führte zu einem unnötigen Sicherheitsweg', '- Zusätzlich gab es falsche Routen für eine Mietüberweisung und eine Kontaktlos-Einstellung sowie eine Fachprüfung statt allgemeiner Anleitung zur Empfängerprüfung', '- Diese Beobachtungen beschreiben Fehler in diesem Satz, nicht deren interne Ursache oder ihre Häufigkeit in echten Tickets','', '## Nachvollziehbarkeit','', '- Jede Fehlentscheidung: [ERRORS.md](ERRORS.md)', '- Rohwerte, alle Optionen und Messdaten: results/predictions.jsonl', '- Konfusionsmatrizen, Strata und Definitionen: results/summary.json', '- Quellen und genaue Grenzen: [SOURCES.md](SOURCES.md)', '- Reproduktion und Dateistruktur: [README.md](README.md)', '- Endgültige unabhängige Scorer-Prüfung: audit/independent_score_check.json','', 'Der Test liefert keine Aussage über reale Kundenzufriedenheit, juristische Korrektheit, Rechtssicherheit, Betrugsdetektionsleistung im Livebetrieb, demografische Fairness oder Produktionsfreigabe. Wahrscheinlichkeiten sind keine kalibrierten Sicherheitsgarantien.']
(R/'REPORT.md').write_text('\n'.join(lines)+'\n')
errors=['# Sämtliche Abweichungen vom eingefrorenen Gold','',f'{len(E)}/80 Fälle haben mindestens ein falsches Feld. Alle Rohwahrscheinlichkeiten bleiben in results/predictions.jsonl und results/errors.jsonl erhalten.','', 'Die unten stehende Begründung erläutert die Referenz nach der fiktiven Policy; sie erklärt nicht den internen Grund der Modellentscheidung. Gold oder Prompts wurden nach dem Lauf nicht angepasst.','']
for e in E:
 errors += [f"## {e['id']}",'',e['message'],'','| Feld | Gold | Clef | Wahrscheinlichkeit der Clef-Wahl |','|---|---|---|---:|']
 for f in ('intent','priority','next_step'):
  pred=e['predicted'][f];errors.append(f"| {f} | {e['expected'][f]} | {pred} | {e['probabilities_unrounded'][f][pred]:.6f} |")
 errors += ['', 'Falsche Felder: '+', '.join(e['incorrect_fields'])+'.','', 'Referenzbegründung: '+e['rationale']]
 if e['clarification_target']:errors+=['', 'Erforderliche Rückfrage laut Testautor: '+e['clarification_target']]
 errors += ['']
(R/'ERRORS.md').write_text('\n'.join(errors)+'\n')
print(f'Reports written: {len(E)} errors, exact {fm(S["metrics"]["all_fields_exact"])}')
